def expand(items, w):
    out = []
    for it in items:
        if it == 'W':
            out.extend(w)
        elif it[0] == 'R':
            out.extend(SP(it[1]))
        else:
            out.append((it[1], it[2]))
    return tuple(out)


def waypoints(j, b):
    """The full asserted waypoint chain TOP5 -> ... -> TOP6
    (plus the r6 = 2 / r6 = 4 closing waypoints)."""
    r6 = 2 * j - 268498
    w = W(r6, b)
    tail = ((1, 1),) + tuple(SP(b - 1))
    pts = []
    pts.append(('C', TOP5F, 95597, 134246, 2, ((2 * j - 2, 2),) + tail, 1))
    pts.append(('B', TOP5F, 95596, 1, 134246,
                ((2, 2), (2 * j - 2, 2)) + tail, 1))
    pts.append(('C', F6, 134246, 3, 2, ((2 * j - 6, 2),) + tail, 1))
    pts.append(('C', F6, 0, 3, 2, tuple(SP(134246)) + w, 1))
    for (st, pb, A, g0, s, items, G) in CASCADE52_WPS:
        pts.append((st, pb, A, g0, s, expand(items, w), G))
    if r6 == 2:
        pts.append(('B', (175059,) + TOP6F, 323288, 1, 3,
                    tuple(SP(b - 1)), 1))
    if r6 == 4:
        pts.append(('C', TOP6F, 175058, 323286, 2,
                    ((2, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        pts.append(('B', TOP6F, 175057, 1, 323286,
                    ((2, 2), (2, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        pts.append(('B', (323287, 175058) + TOP6F, 3, 1, 3,
                    tuple(SP(b - 1)), 1))
    return pts


def norm(cfg):
    st, pb, A, g0, s, pairs, G = cfg
    return (st, tuple(pb), A, g0, s, tuple(pairs), G)


def awalk(src, max_steps=3000000):
    """Streaming every-step walker: yields the target config of
    EVERY macro/prim step in order (the granularity of the
    annotated step log the CASCADE52 classification was built
    from; swalk/mwalk yield only prim-segment endpoints and
    macro targets, which skips mid-segment waypoints), then a
    final ('STATUS', status, cfg, used_rules) tuple.  O(1)
    memory."""
    cfg = src
    used = set()
    total = 0
    while total < max_steps:
        if cfg[0] == 'B' and not cfg[5]:
            yield ('STATUS', 'DONE', cfg, used)
            return
        hit = None
        for mac in MACROS:
            hit = mac(cfg)
            if hit:
                break
        if hit:
            cfg = hit[2]
            total += 1
            yield cfg
            continue
        opts = step_all(cfg)
        assert len(opts) == 1, ('walk stuck/branching', cfg)
        used.add(opts[0][0])
        cfg = opts[0][1]
        total += 1
        yield cfg
    yield ('STATUS', 'CAP', cfg, used)


def check_chain(j, b, cap=3000000):
    pts = [norm(p) for p in waypoints(j, b)]
    pos = -1
    status = fin = None
    used = set()
    nrec = 0
    for rec in awalk(TOP5(j, b), max_steps=cap):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            status, fin, used = rec[1], rec[2], rec[3]
            break
        nrec += 1
        if pos + 1 < len(pts):
            t = pts[pos + 1]
            if rec[0] == t[0] and rec[2] == t[2] and rec[3] == t[3] \
                    and rec[4] == t[4] and (rec == t or norm(rec) == t):
                pos += 1
    assert pos == len(pts) - 1, \
        'j=%d b=%d: waypoint %d missing: %s' \
        % (j, b, pos + 1, fmt(pts[pos + 1]))
    return status, fin, pos, used


def main():
    fails = 0
    used = set()
    # Part 1: full waypoint chain TOP5 -> TOP6, several bands.
    for (j, b) in [(134250, 2), (134250, 3), (134251, 2), (200000, 2),
                   (457538, 2)]:
        try:
            status, fin, pos, u = check_chain(j, b)
            used.update(u)
            print('PASS chain j=%d b=%d: %d waypoints in order, '
                  'walk %s' % (j, b, len(waypoints(j, b)), status))
        except AssertionError as e:
            fails += 1
            print('FAIL', e)
    # Part 1b: CASCADE52 is tail-general -- junk tail probe.
    w0 = ((7, 2), (1, 1), (3, 2), (1, 2))
    src = ('C', F6, 0, 3, 2, tuple(SP(134246)) + w0, 1)
    top6 = norm(('B', TOP6F, 175058, 1, 323287, w0, 1))
    ok = False
    for rec in swalk(src, max_steps=600000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if norm(rec) == top6:
            ok = True
    print(('PASS' if ok else 'FAIL'),
          'tail-generality: TOP6 shape reached with junk tail')
    fails += 0 if ok else 1
    # Part 2: TOP6-closing finals.
    F8 = (175059,) + TOP6F
    F9 = (323287, 175058) + TOP6F
    finals = {
        (134250, 2): (F8, 323289),
        (134250, 3): (F8, 323290),
        (134251, 2): (F9, 4),
        (134251, 3): (F9, 5),
        (134252, 2): (F9, 6),
        (134253, 2): (F9, 8),
        (134253, 3): (F9, 9),
        (200000, 3): (F9, 131503),
        (457538, 2): (F9, 646578),
    }
    for (j, b), (fr, A) in sorted(finals.items()):
        status = fin = None
        for rec in swalk(TOP5(j, b), max_steps=3000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                status, fin = rec[1], rec[2]
                break
        want = ('B', tuple(fr), A, 1, 2 * b + 1, (), 1)
        ok = status == 'DONE' and norm(fin) == want
        print(('PASS' if ok else 'FAIL'),
              'final j=%d b=%d: %s (want A=%d frame %s)'
              % (j, b, fmt(fin), A, list(fr)))
        fails += 0 if ok else 1
    # Part 3: the seventh fence -- r6 >= 646580 takes DIPGRIND
    # at 323286.
    for (j, b) in [(457539, 2), (457540, 2), (500000, 2)]:
        r6 = 2 * j - 268498
        g7 = norm(('C', F7, 323286, 3, 2,
                   ((r6 - 6, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        dip7 = norm(('C', F7, 0, 3, 2,
                     tuple(SP(323286))
                     + ((r6 - 646578, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        seen_g7 = seen_dip7 = False
        for rec in swalk(TOP5(j, b), max_steps=3000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                break
            n = norm(rec)
            if n == g7:
                seen_g7 = True
            elif seen_g7 and n == dip7:
                seen_dip7 = True
                break
        ok = seen_g7 and seen_dip7
        print(('PASS' if ok else 'FAIL'),
              'fence j=%d: GRIND7 then seventh DIPGRIND landing '
              'occur (r6=%d)' % (j, r6))
        fails += 0 if ok else 1
    # Part 4: primitive-step audit.
    bad = used - PROVED_RULES
    print(('PASS' if not bad else 'FAIL'),
          'primitive rules used %s all in PROVED_RULES'
          % (sorted(used),))
    fails += 0 if not bad else 1
    print()
    print('ALL PHASE 52 CHECKS PASS' if fails == 0
          else '%d FAILURES' % fails)
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
